	T.settle(w)
	local t = r.env.time()
	r.W.db.rainchecks = {
		Ani00001 = { driverKey = "anita lift", driver = T.ANITA, service = "Anita Lift", cover = 5000, expires = t + 86400, state = "offered", rideId = "AAAAAA", at = t },
